#!/bin/sh

if [ $# -lt 3 ]
then
    echo "Usage: $0 srcdir builddir compiler"
    exit 1
fi

# Product metadata, not the builder's identity, host name or absolute paths.
# Preserve the diagnostic fields without embedding personal information.
uname="Darwin 9 i386"
date=""
srcdir="vendor/source/samba-187.8/samba/source"
builddir="LeopardSambaBuild"
compiler="Apple Clang; MacOSX10.5 SDK"
whoami=""
host=""

cat <<EOF
/* This file is automatically generated with "make include/build_env.h". DO NOT EDIT */

#ifndef _BUILD_ENV_H
#define _BUILD_ENV_H

#define BUILD_ENV_UNAME "${uname}"
#define BUILD_ENV_DATE "${date}"
#define BUILD_ENV_SRCDIR "${srcdir}"
#define BUILD_ENV_BUILDDIR "${builddir}"
#define BUILD_ENV_USER "${whoami}"
#define BUILD_ENV_HOST "${host}"
#define BUILD_ENV_COMPILER "${compiler}"
#endif /* _BUILD_ENV_H */
EOF
